#!/usr/bin/env bash
# 幂等的开发环境搭建。用法：bash dev/env/setup.sh
#
# 三件事，顺序不能换：
#   1. 建 dev profile —— **必须从 web 模板建**，因为 preset roster（`agent-preset-registry` 行）
#      只存在于 web-app bundle 里；base/headless 模板没有 roster，preset 无从挂载。
#   2. `dsh plugin add` 装本插件 —— 它把 package.json 的 `dsh.bundle.patch` 注册进 profile：
#      host 面的 `assistant-memory` 服务行与 assistant preset 的定义（`cordis.patch.yml` 的
#      `preset-assistant` 行）由此进入组合。
#   3. 默认 preset 由本包的 bundle patch 提供（`- id: agent-preset-registry` 整行替换），
#      profile 用户层不写；dev-only 行（dev-task 的 roster insert、OV 旋钮）生成为
#      `$DSH_HOME/dev-overlay-<profile>.yml`，由启动器以 `--patch` 注入（docs/dev.md §十）。
#   4. 建**第二个** profile `dev-task`（headless 模板）跑 one-shot —— web 与 headless 的
#      bundle 里都 insert 了 id: code-runtime，混装必撞 duplicate id（DSH 自己也把它列为
#      退役元组）；one-shot 的 runner 行只在 headless bundle 里。
# 另外两件保护性的事：
#   5. 断言 DSH_HOME 不是日用的 ~/.dsh（唯一能大规模写坏日用的单点，fail loud）。
#   6. vendor 产物检查：完整 boot 需要构建出的 lib/（--dump-config 不加载它们，不能作证据）。
set -euo pipefail

repo_root="$(git rev-parse --show-toplevel)"
# shellcheck source=dev/env/env.sh
source "$repo_root/dev/env/env.sh"

if [ -z "${ASSISTANT_DSH_HOME:-}" ] && [ "$DSH_HOME" = "$HOME/.dsh" ]; then
  echo "✗ DSH_HOME resolves to the daily ~/.dsh — refusing to touch it." >&2
  echo "  Unset it, source dev/env/env.sh, or point ASSISTANT_DSH_HOME at a scratch home on purpose." >&2
  exit 1
fi

if [ ! -f "$repo_root/vendor/dsh/packages/boot/app-boot/lib/index.js" ] || \
   [ -z "$(find "$repo_root/vendor/dsh/packages/client" -maxdepth 3 -name index.js -path '*/lib/*' -print -quit 2>/dev/null)" ]; then
  echo "✗ vendor/dsh is not built (host lib / client bundles missing) — the harness needs its built lib/ to boot." >&2
  echo "  Run once per pin: bash dev/env/prepare.sh" >&2
  echo "  (it wraps: pnpm --dir vendor/dsh install; build:native-system; build:lib; build:web)" >&2
  exit 1
fi

profile="${ASSISTANT_DEV_PROFILE:-dev}"
profile_dir="$DSH_HOME/profiles/$profile"

if [ -n "${DSH_BIN:-}" ]; then
  run_dsh() { "$DSH_BIN" "$@"; }
else
  # 从钉住的源码启动必须带运行期解析门面（tsconfig.tsx.json），否则 tsx 解析到
  # 未构建的 lib/index.js —— ERR_MODULE_NOT_FOUND（handoff 坑 #3，实跑踩实过）。
  run_dsh() { TSX_TSCONFIG_PATH="$repo_root/tsconfig.tsx.json" node --import tsx/esm "$repo_root/vendor/dsh/apps/cli/src/bin.ts" "$@"; }
fi

if [ ! -d "$profile_dir" ]; then
  echo "▸ creating profile '$profile' from the shipped web template"
  run_dsh --profile "$profile" --from-default-profile web --dump-config > /dev/null
  if [ ! -f "$profile_dir/package.json" ]; then
    echo "✗ profile was not created. Run this once by hand, then Ctrl-C, and re-run this script:" >&2
    echo "    pnpm dsh --profile $profile --from-default-profile web" >&2
    exit 1
  fi
else
  echo "▸ profile '$profile' already exists"
fi

# web 模板 profile 保持 [base, web-app, 本插件]；若历史上加过 headless bundle，摘掉
# （它和 web-app 都 insert id: code-runtime，组合必撞）。幂等自愈。
node -e '
const fs = require("fs")
const file = process.argv[1]
const manifest = JSON.parse(fs.readFileSync(file, "utf8"))
const bundles = manifest.dsh.profile.bundles
const clean = bundles.filter(b => b !== "@deepseek-ai/dsh-headless")
if (clean.length !== bundles.length) {
  manifest.dsh.profile.bundles = clean
  fs.writeFileSync(file, JSON.stringify(manifest, null, 2) + "\n")
}
' "$profile_dir/package.json"

# headless 模板 profile（one-shot）：base + headless，没有 web-app —— roster 行由
# dev/profiles/profile-patch-headless.yml 用 insert 语义补进来（web 模板的行在它里面不存在）。
task_profile="${ASSISTANT_DEV_TASK_PROFILE:-dev-task}"
task_dir="$DSH_HOME/profiles/$task_profile"
if [ ! -d "$task_dir" ]; then
  echo "▸ creating profile '$task_profile' from the shipped headless template"
  run_dsh --profile "$task_profile" --from-default-profile headless --dump-config > /dev/null
  if [ ! -f "$task_dir/package.json" ]; then
    echo "✗ $task_profile was not created." >&2
    exit 1
  fi
fi

# ── profile 用户层零写入（docs/dev.md §十）─────────────────────────────────────
# dev-only 行（dev-task 的 roster insert、OpenViking v3 旋钮）不再写进 profile 的
# cordis.patch.yml：它们生成到 `$DSH_HOME/dev-overlay-<profile>.yml`，由启动器按 profile 用
# `--patch` 注入（`--patch` 可重复，调用者自己的 patch 仍会叠加在后面）。这样 dev 组合与用户
# 装出来的组合只差在 overlay 这一层，而不是差在 "谁手写过 profile"。
overlay_for() { printf '%s/dev-overlay-%s.yml' "$DSH_HOME" "$1"; }
ov_plugin_present() { grep -q '"@openviking/dsh-memory-plugin"' "$1/package.json" 2>/dev/null; }

write_dev_overlay() { # <profile-name> <profile-dir> <base-patch-file-or-empty>
  local name="$1" dir="$2" base="$3" overlay ov=false content
  overlay="$(overlay_for "$name")"
  ov_plugin_present "$dir" && ov=true
  if [ -z "$base" ] && [ "$ov" = false ]; then
    if [ -f "$overlay" ] && grep -q 'Generated by dev/env/setup.sh' "$overlay"; then rm -f "$overlay"; fi
    echo "▸ no dev overlay for '$name' (the profile user layer stays untouched)"
    return 0
  fi
  content="$( {
    printf '# Generated by dev/env/setup.sh — dev-only overlay for profile %s.\n' "$name"
    printf '# Injected by dev/env/dsh.mjs as --patch; the profile user layer stays untouched.\n'
    if [ -n "$base" ]; then cat "$base"; fi
    if [ "$ov" = true ]; then cat "$repo_root/dev/profiles/profile-patch-ov.yml"; fi
  } )"
  # 内容没变就不要重写：mtime 是 `pnpm start` 复用判据的一部分（dev/env/instance.mjs 拿
  # overlay 的 mtime 比实例启动时刻）。每次启动都摸一遍等于让"复用"永远看到过期产物。
  if [ -f "$overlay" ] && [ "$(cat "$overlay")" = "$content" ]; then
    echo "▸ dev overlay for '$name' unchanged"
    return 0
  fi
  printf '%s\n' "$content" > "$overlay"
  echo "▸ wrote the dev overlay for '$name' → $overlay"
}

# 旧版 setup.sh 把生成的行写进了 profile 用户层（registry override / headless roster / OV 旋钮）。
# 新约定下这些行只住在 overlay 里：完全由生成器写成的 patch 复位；用户自己加过行的文件一律不动。
dev_patch_marker() { printf '%s\n' '^# (开发用 profile patch|headless 模板只有|OpenViking 记忆层的 v3 旋钮|Generated by dev/env/setup.sh)'; }
reset_dev_profile_patch() { # <profile-name> <profile-dir>
  local name="$1" file="$2/cordis.patch.yml"
  [ -f "$file" ] || return 0
  if ! grep -qE "$(dev_patch_marker)" "$file"; then return 0; fi
  if grep -E '^- ' "$file" | grep -vqE '^- (id: (agent-preset-registry|openviking-memory-runtime|assistant-product|schedule)|insert:)$'; then
    echo "⚠ '$name' 的 profile patch 含生成器不认识的行——保留原文件，人工确认（docs/dev.md §十）" >&2
    return 0
  fi
  cp "$file" "$file.dev-backup"
  printf '# Your patch layer for this dsh profile, applied after every bundle layer.\n# dev-only rows travel as --patch overlays (docs/dev.md §十).\n[]\n' > "$file"
  echo "▸ reset the dev-generated profile patch for '$name' (backup: $file.dev-backup)"
}

# 「已经装好就跳过」的判据住在 dev/env/plugin-link.mjs（三条件同时成立才跳过：bundles 点名、
# 依赖是同一路径的 link、清单指纹未变）。实测（2026-11-05）两段 plugin add 占 `pnpm start`
# 12.4s 里的 ≈4s，而它们只在插件清单/profile 变过时才可能有不同结果。
# `ASSISTANT_FORCE_PLUGIN_ADD=1` 是无条件重装的口子（怀疑"跳过导致的不生效"时用）。
package_dir="$repo_root/packages/dsh-smart-assistant"
plugin_link() { node "$repo_root/dev/env/plugin-link.mjs" "$@"; }

for pair in "$profile:$profile_dir:$repo_root/dev/profiles/profile-patch-dev.yml" \
            "$task_profile:$task_dir:$repo_root/dev/profiles/profile-patch-headless.yml"; do
  name="${pair%%:*}"
  rest="${pair#*:}"
  dir="${rest%%:*}"
  patch="${rest#*:}"
  if [ -z "${ASSISTANT_FORCE_PLUGIN_ADD:-}" ] && plugin_link --check "$dir" "$package_dir" >/dev/null 2>&1; then
    echo "▸ '$name' already links the plugin (manifest unchanged) — skipping plugin add"
  else
    echo "▸ installing the plugin bundle into '$name'"
    # 裸路径 = pnpm 的 link 语义（symlink 回本 repo）：改 src 后只需 `pnpm build` 重建 lib，
    # 不必重新 add。`file:` 前缀是复制语义，开发环用它会"改了不生效"。
    run_dsh plugin --profile "$name" add "$package_dir"
    plugin_link --stamp "$dir" "$package_dir"
  fi
  reset_dev_profile_patch "$name" "$dir"
  write_dev_overlay "$name" "$dir" "$patch"
done

# 6.5. OpenViking 记忆层的 server（幂等；**失败不阻断**——可选增强不能成单点故障）。
# 它是独立进程，插件拉起不了（产物里没有 spawn），而插件连不上时静默降级、界面看不出来，
# 所以「起服务」这一串里必须有这一步，否则记忆层在不在全靠人记着敲。细节见脚本头注。
echo "▸ OpenViking 记忆层（可选；缺席不阻断）"
bash "$repo_root/dev/env/openviking-up.sh" || true

echo
echo "done. Next:"
echo "  pnpm dsh --profile $task_profile \"one task\"   # host-only one-shot: plugin load/scaffold/service smoke (headless)"
echo "  pnpm dsh --profile $task_profile --patch dev/probes/session/preset-runner.patch.yml \"one task\"   # one-shot through the assistant preset"
echo "  pnpm dsh --profile $profile                    # Web UI (the profile carries the web-app bundle)"
echo
echo "  ⚠ not 'pnpm dsh web': the 'web' alias hardcodes profile 'web' and would create a"
echo "    shipped 'web' profile inside the dev home."
echo
echo "Discipline: preset rows load the built lib/ — 'pnpm start' self-checks against src/ and 'pnpm"
echo "verify' gates it ('build:'); rebuild by hand with 'pnpm build'."
echo "Skill edits (presets/assistant/skills/) need no rebuild — the catalog is re-scanned per"
echo "request. Composition edits (cordis.patch.yml) reach new sessions with the next"
echo "generation (file mtime+size stamp); sessions already running keep theirs."
echo
echo "Note: the home lives at $DSH_HOME — the daily ~/.dsh is untouched."
